private void assertAcyclic(List<String[]> edges) {
    Map<String, Integer> indegree = new HashMap<>();
    Map<String, List<String>> adj = new HashMap<>();
    for (String[] e : edges) {
        adj.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
        indegree.merge(e[1], 1, Integer::sum);
        indegree.putIfAbsent(e[0], 0);
    }
    Deque<String> queue = ...nodes with 0 indegree;
    int visited = 0;
    while (!queue.isEmpty()) { node = poll; visited++; for next: decrement, if 0 offer }
    if (visited != indegree.size()) throw conflict PATH_CYCLE;
}
