    void edgeCapacityLimitsApprovedFlowSum() throws Exception {
        long windowId = createGraphWindow("ch-cap-" + run, "100", List.of("A", "B"),
                List.of(edge("A", "B", 3)));
        String a1 = submitPath(windowId, "user-1", "5", List.of("A", "B"), 2, "alice");
