        postJson("/api/allocations",
                pathAllocationBody(key("ac"), key("ak"), windowId, "u", "1", null, null), "alice", 400);
        // 普通窗口不适用门禁：携带路径 -> 400
        long plainWindow = createPlainWindow("ch-plain-" + run, "100");
        postJson("/api/allocations",
