                "alice", 400);
        // 普通窗口正常申请不受影响
        String plain = key("ak");
        postOk("/api/allocations",
                pathAllocationBody(key("ac"), plain, plainWindow, "u", "1", null, null), "alice");
        approve(plain, 200);
    }

